/// Every selectable country, sorted by display name.
pub fn countries() -> Vec<(&'static str, &'static str)> {
    let mut all: Vec<_> = SHIFTER_POOL_COUNTRIES
        .iter()
        .chain(GLOBAL_POOL_COUNTRIES)
        .copied()
        .collect();
    all.sort_by_key(|(_, name)| *name);
    all
}
pub fn valid_country(country: &str) -> bool {
    shifter_pool(country)
        || GLOBAL_POOL_COUNTRIES
            .iter()
            .any(|(code, _)| *code == country)
}
pub fn shifter_pool(country: &str) -> bool {
    SHIFTER_POOL_COUNTRIES
        .iter()
        .any(|(code, _)| *code == country)
}
pub fn random_id() -> String {
    hex::encode(rand::random::<[u8; 16]>())
}
pub fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}
pub fn is_id(s: &str) -> bool {
    s.len() == 32 && s.bytes().all(|c| c.is_ascii_hexdigit())
}

